import type { CalculatorDef, CalculatorField, CalculatorResult } from "./types";

// Monthly, end-of-period cash-flow models. Defaults are examples, not statutory rates or product quotes.
const won = (name: string, label: string, value: number): CalculatorField => ({ name, label, defaultValue: value, suffix: "원", min: 0, max: 1e12, step: 1000, hint: "실제 금액 또는 비교할 가정값을 원 단위로 입력하세요." });
const num = (name: string, label: string, value: number, suffix: string, min = 0, max = 600, step = 1): CalculatorField => ({ name, label, defaultValue: value, suffix, min, max, step, hint: `${min}~${max}${suffix} 범위의 가정값입니다.` });
const rate = (name = "rate", label = "가정 연이율", value = 4) => num(name, label, value, "%", 0, 50, 0.1);
const months = (name = "months", label = "기간", value = 36) => num(name, label, value, "개월", 1, 600);
const pct = (name: string, label: string, value: number) => num(name, label, value, "%", 0, 100, 0.1);
const R = (label: string, value: number, suffix = "원") => {
  const precision = suffix === "원" || suffix === "개월" ? 1 : 100;
  const rounded = Math.round(value * precision) / precision;
  return { label, value: rounded === 0 ? 0 : rounded, suffix };
};
const result = (label: string, value: number, secondary: NonNullable<CalculatorResult["secondary"]> = [], note?: string, suffix = "원"): CalculatorResult => ({ primary: R(label, value, suffix), secondary, note });
const invalid = (note: string): CalculatorResult => ({ ...result("입력 조건 확인", 0, [], note), status: "invalid" });
const monthly = (annual: number) => annual / 1200;
const payment = (p: number, r: number, n: number) => r === 0 ? p / n : p * r / -Math.expm1(-n * Math.log1p(r));
const growth = (r: number, n: number) => Math.exp(n * Math.log1p(r));
const factor = (r: number, n: number) => r === 0 ? n : Math.expm1(n * Math.log1p(r)) / r;
const fv = (p: number, m: number, r: number, n: number) => p * growth(r, n) + m * factor(r, n);
const needMonthly = (goal: number, p: number, r: number, n: number) => Math.max(0, (goal - p * growth(r, n)) / factor(r, n));

function payoff(p: number, r: number, pay: number, limit = 600) {
  let balance = p, interest = 0, paid = 0, count = 0;
  while (balance > 0.005 && count < limit) {
    const charge = balance * r;
    if (pay <= charge) return { months: count, interest, paid, balance, finished: false };
    const actual = Math.min(pay, balance + charge);
    balance = Math.max(0, balance + charge - actual);
    interest += charge; paid += actual; count++;
  }
  return { months: count, interest, paid, balance, finished: balance <= 0.005 };
}

